form.script:


                        $(".country_of_incorporation").change(function()
                        {
                            var e = document.getElementById("country_id");
                            var opt_text = e.options[e.selectedIndex].text;
                            if(opt_text=="China")
                            {
                                $('input:radio[id=china]').prop("checked",true);
                            }
                            else if(opt_text=="United Arab Emirates")
                            {
                                $('input:radio[id=uae]').prop("checked",true);
                            }
                            else
                            {
                                $('input:radio[id=other]').prop("checked",true);
                            }
                        });


