                        function ajaxpost(){

                            var check = check_required_fields()

                            if (check == false)
                            {
                                alert("Please fill all required fields !!");
                                return false;
                            }


                            var submit_flag = true;









                            // (A) GET FORM DATA
                            var form = document.getElementById("vendorRegistrattionForm");


                            var data = new FormData(form);

					        console.log(data)

                            // (B) AJAX REQUEST
                            // (B1) POST DATA TO SERVER, RETURN RESPONSE AS TEXT
                            fetch("/vendor/registration/submit", { method:"POST", body:data })
                            .then(res=>res.text())

                            // (B2) SHOW MESSAGE ON SERVER RESPONSE
                            .then((response) => {

					console.log(response);
                                console.log("submit_flag=====22====",submit_flag)

                                if (submit_flag == true){
                                    if (response == "OK") {
                                        alert("You Vendor Registration is Successfully Registered!");
                                        window.location.reload();
                                    }
                                    else {
                                         alert("Something went Wrong!"); 
                                         }
                                }
                            })

                            // (B3) OPTIONAL - HANDLE FETCH ERROR
                            .catch((err) => { console.error(err); });

                            // (C) PREVENT FORM SUBMIT
                            return false;
                        }
